// Eingabe der Runtime: { start, end, calendar?, limit? }
const incoming = $input.first().json;
const inp = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
if (typeof inp.start !== 'string' || typeof inp.end !== 'string') {
  throw new Error('cal-list: Felder "start" und "end" (ISO 8601) sind erforderlich');
}
return [{ json: {
  timeMin: inp.start,
  timeMax: inp.end,
  calendar: typeof inp.calendar === 'string' && inp.calendar ? inp.calendar : 'primary',
  limit: Number.isFinite(Number(inp.limit)) ? Number(inp.limit) : 100
} }];

// Alle Termine in die von der Runtime erwartete Form bringen.
const events = $input.all().map((item) => {
  const e = item.json || {};
  const start = (e.start && (e.start.dateTime || e.start.date)) || e.start || '';
  const end = (e.end && (e.end.dateTime || e.end.date)) || e.end || '';
  return {
    id: String(e.id || ''),
    title: e.summary || '(kein Titel)',
    start,
    end,
    all_day: !!(e.start && e.start.date && !e.start.dateTime),
    location: e.location || '',
    calendar: (e.organizer && e.organizer.email) || e.calendarId || '',
    status: e.status || '',
    description: e.description || ''
  };
});
return [{ json: { events } }];
